insert into public.ai_settings (business_id, tone, extra_instructions) values ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'warm, welcoming and concise, like a Kenyan coastal concierge', 'Use a light Swahili greeting (Jambo, Karibu, Asante) where natural. Prices are in Kenyan Shillings (KES).')
insert into public.knowledge_items (business_id, category, title, content, price, price_unit, metadata, sort_order) values
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'hours', 'Reception', 'Open 24 hours, every day.', null, null, '{}'::jsonb, 0),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'hours', 'Check-in and check-out', 'Check-in from 2:00 pm. Check-out by 11:00 am. Late check-out until 3:00 pm can be requested and depends on availability (KES 4,000).', null, null, '{}'::jsonb, 1),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'hours', 'Pwani Restaurant', 'Breakfast 6:30 am to 10:30 am. Lunch 12:30 pm to 3:30 pm. Dinner 7:00 pm to 10:30 pm. Open every day, including public holidays.', null, null, '{}'::jsonb, 2),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'hours', 'Mvua Spa', '9:00 am to 8:00 pm daily. Last treatment starts at 7:00 pm.', null, null, '{}'::jsonb, 3),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'hours', 'Pool and beach bar', 'Infinity pool 7:00 am to 8:00 pm. Beach bar 10:00 am to 11:00 pm.', null, null, '{}'::jsonb, 4),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'room', 'Garden Room', '28 m², queen bed, garden view, air conditioning, rain shower, free Wi-Fi. Sleeps up to 2 adults.', 14500, 'per night, bed & breakfast for 2', '{}'::jsonb, 5),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'room', 'Ocean View Room', '34 m², king or twin beds, private balcony facing the Indian Ocean, air conditioning, minibar. Sleeps up to 2 adults and 1 child under 12.', 21000, 'per night, bed & breakfast for 2', '{}'::jsonb, 6),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'room', 'Family Suite', '62 m², two bedrooms (king + twin), living area, garden terrace, two bathrooms. Sleeps up to 4 adults or 2 adults and 3 children.', 34000, 'per night, bed & breakfast for 4', '{}'::jsonb, 7),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'room', 'Beachfront Villa', '110 m², private plunge pool, direct beach access, outdoor shower, butler service. Sleeps up to 2 adults.', 58000, 'per night, half board for 2', '{}'::jsonb, 8),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'facility', 'Infinity pool', 'Heated infinity pool overlooking the ocean, with a separate shallow children''s pool. Towels provided.', null, null, '{}'::jsonb, 9),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'facility', 'Mvua Spa', 'Four treatment rooms, steam room and couples'' suite. Signature 60-minute Swahili coconut massage.', null, null, '{}'::jsonb, 10),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'facility', 'Wi-Fi and workspace', 'Free high-speed Wi-Fi throughout the resort and a quiet co-working lounge by the lobby.', null, null, '{}'::jsonb, 11),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'facility', 'Parking', 'Free secure parking for guests, with 24-hour security.', null, null, '{}'::jsonb, 12),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'facility', 'Kids'' club', 'Supervised kids'' club for ages 4 to 12, 9:00 am to 5:00 pm. Free for staying guests.', null, null, '{}'::jsonb, 13),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'service', 'Airport transfer', 'Private transfer from Ukunda Airstrip (10 minutes) or Moi International Airport, Mombasa (about 1 hour 30 minutes).', 6500, 'one way from Mombasa, up to 4 people', '{}'::jsonb, 14),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'service', 'Swahili coconut massage', '60-minute full-body massage with warm coconut oil.', 7500, 'per person', '{}'::jsonb, 15),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'service', 'Snorkelling trip to Kisite Marine Park', 'Full-day dhow trip with snorkelling gear, seafood lunch and park fees. Runs Tuesday, Thursday and Saturday.', 12000, 'per adult', '{}'::jsonb, 16),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'service', 'Laundry', 'Same-day laundry if handed in before 10:00 am. Priced per item; see the list in your room.', null, null, '{}'::jsonb, 17),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Swahili breakfast', 'Mandazi, chai masala, tropical fruit, eggs any style. Included in all room rates.', 1800, 'per person for non-residents', '{"course":"breakfast"}'::jsonb, 18),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Grilled catch of the day', 'Fresh reef fish with coconut rice, kachumbari and tamarind sauce.', 2400, 'per plate', '{"course":"main"}'::jsonb, 19),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Prawn pilau', 'Spiced Lamu-style pilau with king prawns and raita.', 2900, 'per plate', '{"course":"main"}'::jsonb, 20),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Coconut bean curry (vegan)', 'Red kidney beans in coconut curry with chapati or rice. Vegan and gluten-free on request.', 1500, 'per plate', '{"course":"main","dietary":["vegan"]}'::jsonb, 21),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Nyama choma platter', 'Charcoal-grilled goat ribs with ugali, sukuma wiki and kachumbari. Serves 2.', 3600, 'per platter', '{"course":"main"}'::jsonb, 22),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Mango and passion sorbet', 'House-made, dairy-free.', 750, 'per bowl', '{"course":"dessert"}'::jsonb, 23),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'menu_item', 'Dawa cocktail', 'Vodka, lime, honey and crushed ice. Non-alcoholic version available.', 900, 'per glass', '{"course":"drinks"}'::jsonb, 24),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Cancellation policy', 'Free cancellation up to 7 days before arrival. Cancellations within 7 days are charged one night. No-shows are charged the full stay.', null, null, '{}'::jsonb, 25),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Deposit', 'A 30% deposit by M-Pesa or card is needed to secure a room booking once the reservation team confirms availability.', null, null, '{}'::jsonb, 26),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Children', 'Children under 4 stay free in their parents'' room. Children 4 to 11 sharing with parents pay KES 3,500 per night including breakfast.', null, null, '{}'::jsonb, 27),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Pets', 'Pets are not allowed, except registered assistance animals.', null, null, '{}'::jsonb, 28),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Restaurant reservations', 'Table bookings are recommended for dinner. Groups larger than 10 must be arranged with the restaurant manager. Tables are held for 15 minutes.', null, null, '{}'::jsonb, 29),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'policy', 'Payment methods', 'M-Pesa, Visa, Mastercard and cash (KES, USD, EUR).', null, null, '{}'::jsonb, 30),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'offer', 'Stay 4, pay 3', 'Book 4 nights in any room type and the 4th night is free. Valid for stays from 1 February to 31 March 2027. Not combinable with other offers.', null, null, '{}'::jsonb, 31),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'offer', 'Sunset seafood night', 'Every Friday from 7:00 pm: seafood buffet with live taarab music on the beach.', 4500, 'per person', '{}'::jsonb, 32),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'faq', 'Is breakfast included?', 'Yes. All room rates include breakfast at Pwani Restaurant. The Beachfront Villa includes breakfast and dinner.', null, null, '{}'::jsonb, 33),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'faq', 'Do you accept walk-in diners?', 'Yes, non-residents are welcome at Pwani Restaurant. Booking ahead for dinner is recommended, especially on Fridays.', null, null, '{}'::jsonb, 34),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'faq', 'How far is the resort from the airport?', '10 minutes from Ukunda Airstrip and about 1 hour 30 minutes from Moi International Airport in Mombasa, depending on the Likoni ferry.', null, null, '{}'::jsonb, 35),
  ('6f1d2c3b-4a5e-4f60-8a7b-9c0d1e2f3a4b', 'faq', 'Can you cater for dietary needs?', 'Yes. Vegetarian, vegan, halal and gluten-free meals are available. Please mention allergies when booking.', null, null, '{}'::jsonb, 36);
